// src/App.js
import React, { useState } from 'react';
import axios from 'axios';
import CodeEditor from './components/CodeEditor';
import './App.css';

function App() {
    const [language, setLanguage] = useState('javascript');
    const [code, setCode] = useState('// Write your code here...');
    const [output, setOutput] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    // Function to execute code when the button is clicked
    const handleRunCode = async () => {
        setIsLoading(true);
        setOutput(''); // Clear previous output

        // 1. Client-Side Execution (HTML/CSS/JS bundled)
        if (language === 'html') {
            // For HTML, the output state just holds the raw code to feed to the iframe
            setOutput(code);
            setIsLoading(false);
            return;
        }

        // 2. Server-Side Execution (Python, Java, C, JS)
        try {
            // Send the code to our local Node.js backend
            const response = await axios.post('http://localhost:5000/api/code/execute', {
                language: language,
                code: code
            });

            // Set the standard output returned from Piston
            setOutput(response.data.output);
        } catch (error) {
            // Handle compilation errors or backend server errors
            const errorMsg = error.response?.data?.output || error.response?.data?.message || "An error occurred connecting to the server.";
            setOutput(errorMsg);
        } finally {
            setIsLoading(false);
        }
    };

    // Update default code when language changes
    const handleLanguageChange = (e) => {
        const newLang = e.target.value;
        setLanguage(newLang);
        if (newLang === 'html') setCode('<h1>Hello World</h1>\n<style>\n  h1 { color: blue; }\n</style>');
        else if (newLang === 'python') setCode('print("Hello from Python!")');
        else if (newLang === 'java') setCode('public class Main {\n  public static void main(String[] args) {\n    System.out.println("Hello from Java!");\n  }\n}');
        else if (newLang === 'c') setCode('#include <stdio.h>\n\nint main() {\n  printf("Hello from C!\\n");\n  return 0;\n}');
        else setCode('console.log("Hello World");');
    };

    return (
        <div className="ide-container">
            <header className="header">
                <h2>eLearning IDE</h2>
                <div className="controls">
                    <select value={language} onChange={handleLanguageChange}>
                        <option value="javascript">JavaScript (Node)</option>
                        <option value="html">HTML/CSS/JS (Web)</option>
                        <option value="python">Python</option>
                        <option value="java">Java</option>
                        <option value="c">C</option>
                    </select>
                    <button onClick={handleRunCode} disabled={isLoading}>
                        {isLoading ? 'Running...' : 'Run Code'}
                    </button>
                </div>
            </header>

            <div className="main-content">
                <CodeEditor 
                    language={language === 'html' ? 'html' : language} 
                    code={code} 
                    setCode={setCode} 
                />

                <div className="output-section">
                    <h3>Output</h3>
                    <div className="output-box">
                        {/* If HTML is selected, render an iframe. Otherwise, render raw text. */}
                        {language === 'html' && output ? (
                            <iframe 
                                srcDoc={output} 
                                title="output"
                                sandbox="allow-scripts" // Security constraint for iframe
                                style={{ width: '100%', height: '100%', border: 'none', backgroundColor: '#fff' }}
                            />
                        ) : (
                            <pre style={{ margin: 0 }}>
                                {output || "Click 'Run Code' to see the output here."}
                            </pre>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default App;
